contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint mode) public {
        require(mode <= 1);
        if (mode == 1) {
            // first call gives this contract 20 tokens
            bool ok1;
            try c.airDrop() { ok1 = true; } catch { ok1 = false; }
            require(ok1);
        }
        uint before = c.tokenBalance(address(this));
        bool reverted;
        try c.airDrop() { reverted = false; } catch { reverted = true; }
        uint afterB = c.tokenBalance(address(this));
        if (mode == 0) {
            assert(!reverted && afterB == before + 20);
        } else {
            assert(reverted && afterB == before);
        }
    }

    fallback() external payable {
        // Bank(msg.sender).supportsToken() lands here; return the expected hash
        assembly {
            mstore(0, keccak256(abi.encodePacked("Nu Token")), 32)
        }
        // solhint-disable
    }

    receive() external payable {}
}

