contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Make the test contract itself a valid Bank-like caller so airDrop succeeds.
    fallback(bytes calldata) external payable returns (bytes memory) {
        bytes32 h = keccak256(abi.encodePacked("Nu Token"));
        return abi.encode(h);
    }

    function run(uint256 ignore) public {
        require(ignore >= 0);
        require(c.tokenBalance(address(this)) == 0);

        uint256 before1 = c.tokenBalance(address(this));
        c.airDrop();
        uint256 after1 = c.tokenBalance(address(this));

        bool reverted2;
        try c.airDrop() { reverted2 = false; } catch { reverted2 = true; }
        uint256 after2 = c.tokenBalance(address(this));

        assert(before1 == 0 && after1 == 20 && reverted2 && after2 == 20);
    }

    receive() external payable {}
}

