contract InvMutTest {
    C c;
    bool correctHash;

    constructor(C _c) { c = _c; }

    function run(bool useCorrectHash) public {
        require(c.tokenBalance(address(this)) == 0);
        correctHash = useCorrectHash;

        bool reverted1;
        try c.airDrop() { reverted1 = false; } catch { reverted1 = true; }
        uint balAfterFirst = c.tokenBalance(address(this));

        correctHash = true;
        bool reverted2;
        try c.airDrop() { reverted2 = false; } catch { reverted2 = true; }
        uint balAfterSecond = c.tokenBalance(address(this));

        assert(reverted1 == !useCorrectHash
            && (reverted1 ? balAfterFirst == 0 : balAfterFirst == 20)
            && !reverted2 && balAfterSecond == 20);
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        if (correctHash) {
            return abi.encode(keccak256(abi.encodePacked("Nu Token")));
        }
        return abi.encode(keccak256(abi.encodePacked("Wrong")));
    }

    receive() external payable {}
}

